"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[80243],{80243:(e,o,a)=>{a.d(o,{r:()=>s});let t={meta:{title:"4차 포타 혁명 만들기 | 최애나 자캐 폰 꾸미기, 소설 속 커뮤니티 글과 뉴스, 메신저 화면까지 링크로 - Wimo Universe",description:"최애나 자캐의 핸드폰을 잠금 화면부터 메시지, 통화 기록, 메모, 사진첩, SNS까지 꾸며 링크로 건네요. 받은 사람은 비밀번호를 맞혀야 그 폰을 열 수 있어요. 포타 글 사이에 넣을 소설 속 커뮤니티 글, 뉴스 기사, 메신저 대화방, SNS 게시물도 여기서 만들어요. 가입 없이 휴대폰에서 바로 돼요.",ogTitle:"4차 포타 혁명 만들기",ogDescription:"최애 폰을 잠금 화면부터 메시지와 SNS까지 꾸며 링크로 건네요. 소설 속 커뮤니티 글이나 뉴스 기사도 만들 수 있어요.",keywords:["4차 포타 혁명","4차 포타 혁명 만들기","폰 꾸미기","폰 열어보기","핸드폰 엿보기 만들기","자캐 핸드폰","최애 폰 엿보기","포타 핸드폰","포타 연출","포스타입 연출","소설 속 커뮤니티 글 만들기","소설 속 뉴스 기사","메신저 대화 화면 만들기","웹소설 연출","라방 화면 만들기","가짜 라이브 방송"]},page:{title:"4차 포타 혁명 만들기",intro:'포타나 웹소설에 넣을 "소설 속 화면"을 만드는 곳이에요. 처음 열리는 건 폰 꾸미기예요. 최애나 내 캐릭터의 핸드폰에 잠금 화면 알림, 네 자리 비밀번호와 힌트, 메시지 대화, 부재중 전화, 메모, 사진첩, SNS를 채우고 홈 화면에 둘 앱도 골라요. "링크 만들기"를 누르면 받은 사람이 비밀번호를 맞혀 그 폰을 열어 봐요. 폰 밖 장면이 필요하면 위 "소설 속 페이지"에서 익명 커뮤니티 글과 댓글, 인터넷 뉴스 기사, 메신저 대화방, SNS 게시물을 골라 wimouniv.com/pota/ 로 시작하는 짧은 링크로 만들어요.'},related:{before:"자캐 이름을 넣고 ",link:"로판 속 누군가로 랜덤 빙의시켜",after:" 보세요. 사망 플래그를 피해 간 일생이 그 이름이 박힌 결과 카드로 남아요."},headings:{howTo:"쓰는 방법",faq:"자주 묻는 질문",otherTools:"다른 도구"},steps:["처음엔 폰 꾸미기가 열려 있어요. 기본 칸에서 폰 주인 이름, 네 자리 비밀번호, 틀렸을 때 보일 힌트, 배경화면을 정해요. 비밀번호를 비우면 바로 열려요.","홈 화면 칸에서 앱을 켜고 끄거나 아래 독으로 옮겨요. 알림, 메시지, 통화, 메모, 사진, SNS 칸을 채우면 위 폰이 그 앱 화면으로 넘어가서 어떻게 보이는지 알려 줘요.",'통화 칸의 "걸려 오는 전화"와 메시지 칸의 "이어지는 대화"를 넣으면, 보는 사람이 잠금을 푼 뒤 전화를 받거나 키보드를 눌러 이야기를 이어 갈 수 있어요.','"링크 만들기"를 누르면 짧은 링크가 복사돼요. 로그인 없이 만든 링크는 30일 동안 열려요. 포타 글 사이나 X, 카톡에 붙여 넣으면 받은 사람이 잠금을 풀고 앱을 하나씩 열어 봐요.','폰 밖 장면이 필요하면 위 "소설 속 페이지"에서 커뮤니티 글, 뉴스 기사, 메신저, SNS 글, 버블(아이돌 팬 메신저) 중 하나를 골라요. 칸을 채우고 "링크 만들기"를 누르면 짧은 링크가 생기고, 나중에 내용을 고쳐도 같은 링크로 열려요.','소설 속 페이지는 이 브라우저의 "내가 만든 페이지"에 모여요. 다시 불러와 고치거나 링크를 지울 수 있어요.'],faqs:[{q:"4차 포타 혁명이 뭐예요?",a:"포스타입(포타)이나 웹소설 작가들이 글 중간에 주인공의 폰 화면, 소설 속 커뮤니티 글, 뉴스 기사 같은 가짜 화면을 링크로 넣는 연출을 X 에서 이렇게 불러요. 독자는 링크를 눌러 그 세계 안의 폰과 사이트를 직접 들여다보게 돼요. 원래는 AI 웹 빌더로 페이지를 하나씩 짜야 했는데, 여기서는 칸만 채우면 돼요."},{q:"받은 사람은 폰 비밀번호를 어떻게 알아요?",a:"잠금 화면에서 위로 쓸어 올리면 암호 입력 화면이 나와요. 한 번 틀리면 만든 사람이 적은 힌트가 위에 떠요. 캐릭터 생일이나 처음 만난 날처럼 이야기를 아는 사람만 맞힐 수 있는 숫자로 하면 재밌어요. 비밀번호를 비워 두면 바로 홈 화면으로 열려요."},{q:"만든 것은 어디에 저장돼요?",a:"폰과 소설 속 페이지 모두 위모 서버(구글 클라우드 Firestore)에 저장돼요. Google로 로그인하고 저장한 폰은 내 작품함에 계속 남아요. 로그인 없이 만든 폰 링크는 30일 동안 열리고 그 뒤엔 지워지니, 계속 남기려면 그 브라우저에서 로그인해 계정에 넣어 주세요. 고치거나 지울 수 있는 열쇠는 만든 사람 브라우저에 남아요. 비밀번호도 폰 내용에 같이 들어가요. 올린 사진은 위모 저장소에 둬요. 링크를 아는 사람은 누구나 볼 수 있으니 진짜 개인정보나 비밀은 넣지 마세요."},{q:"이미 퍼진 링크의 내용을 바꿀 수 있나요?",a:'소설 속 페이지는 돼요. 만든 브라우저에서 내용을 고친 뒤 "바꾼 내용 저장"을 누르면 같은 링크가 새 내용으로 열려요. 연재 중에 떡밥 댓글을 하나씩 늘리는 식으로 쓸 수 있어요. 폰도 만든 브라우저에서 고친 뒤 "저장하기 (보낸 링크 그대로)"를 누르면 같은 링크가 바뀌어요. 예전에 만든 긴 링크는 내용이 링크 자체에 들어 있어서 고치면 새 링크가 생겨요.'},{q:"홈 화면 앱을 바꿀 수 있나요?",a:"네. 홈 화면 칸에서 앱마다 홈, 아래 독, 끔 중 하나를 고르고 홈 안 순서는 화살표로 바꿔요. 독에는 4개까지 들어가요. 사진 SNS 앱은 이름을 바꿀 수 있고 프로필과 게시물 12개까지 채울 수 있어요. 끈 앱은 홈에서만 빠지고, 잠금 화면 알림을 누르면 그 앱은 열려요."},{q:"사진을 넣을 수 있나요?",a:"네. 폰은 배경화면, 사진첩 18장, SNS 게시물, 메시지와 카톡, 왓츠앱 대화방에 넣을 수 있어요. 소설 속 페이지는 커뮤니티 글과 SNS 글에 4장, 뉴스 기사에 대표 사진 1장, 메신저 말풍선마다 1장까지예요. 올리기 전에 휴대폰 안에서 긴 변 1,600픽셀로 줄여서 보통 한 장에 200~400KB로 올라가고, 줄여도 1MB가 넘는 사진은 받지 않아요. 남의 사진이나 실제 사람 얼굴은 허락 없이 올리지 마세요."},{q:"받은 폰을 고쳐서 내 걸로 만들 수 있나요?",a:'네. 링크로 연 폰 아래 구석의 칩을 누른 뒤 "이 폰 고쳐서 내 거 만들기"를 누르면 그 내용이 편집 칸에 그대로 들어와요. 바꾼 뒤 다시 "링크 만들기"를 누르면 새 링크가 생겨요.'},{q:"전화가 오거나 대화가 이어지게 할 수 있나요?",a:'통화 칸의 "걸려 오는 전화"에 이름과 대사를 넣으면 잠금을 풀고 몇 초 뒤에 전화가 와요. 받으면 대사가 하나씩 뜨고, 안 받으면 남긴 메시지가 대화방에 와요. 메시지 칸의 "이어지는 대화"는 보는 사람이 키보드를 눌러 내 말을 완성하면 상대 말이 이어져요.'},{q:"AI로 만들 수 있나요?",a:'네. 폰 아래 "AI로 채우기"를 누르고 "부탁 문장 복사"로 클로드나 챗GPT에게 안내서를 건네세요. 인물과 상황을 덧붙이면 AI가 알림, 대화, 메모, SNS까지 한 번에 써 줘요. 그 답을 칸에 붙여 넣고 "불러오기"를 누르면 메뉴를 하나씩 채우지 않아도 돼요. 사진과 목소리는 불러온 뒤 직접 올려요.'},{q:"라방(라이브 방송) 화면도 만들 수 있나요?",a:'네. 폰의 "라방" 탭에서 방송하는 사람, 방송 제목, 시청자 수와 하트 수, 배경 사진, 고정 댓글, 댓글을 넣으면 인스타나 위버스 라이브 같은 방송 화면이 열려요. 댓글은 하나씩 떠오르고 하트는 눌러서 띄울 수 있어요. 아이돌 AU나 배우 AU에서 "그날 밤 라방" 장면을 보여 줄 때 좋아요.'},{q:"해외 팬픽(AO3)에도 쓸 수 있나요?",a:"네. 영어판(/en/pota-revolution)에서 똑같이 만들 수 있어요. AO3 본문에는 링크와 그림을 넣을 수 있지만, 유튜브 같은 허용된 몇 곳 말고는 다른 사이트 화면을 끼워 넣을 수 없어요. 그래서 링크를 본문에 걸거나 화면을 캡처해 그림으로 넣는 식으로 써요."},{q:"할로윈 버전도 있나요?",a:'기본 탭 배경화면에 "할로윈 밤"이 있어요. 잠금 화면과 홈이 호박 주황과 짙은 보라로 바뀌어요. 공포 AU 단톡이나 새벽 3시에 이상해지는 라방이랑 같이 써 보세요.'},{q:"누가 나쁘게 쓰면 어떡해요?",a:'실제 사람을 사칭하거나 진짜 대화 캡처, 진짜 사건 기사처럼 꾸며 누군가를 속이는 데 쓰면 안 돼요. 소설 속 페이지 아래에는 "신고" 버튼이 있고, 여러 사람이 신고한 페이지는 자동으로 내려가요. 링크 페이지는 검색에 걸리지 않게 해 두었어요.'}],kinds:{board:"커뮤니티 글",news:"뉴스 기사",chat:"메신저",sns:"SNS 글",bubble:"버블"},hub:{nav:"만들 것",phone:"폰 꾸미기",phoneSub:"잠금 화면부터 메시지, SNS까지",more:"소설 속 페이지",navPages:"만들 화면"},ui:{urlEmpty:"링크를 만들면 주소가 생겨요",dockBig:"미리보기 크게",dockSmall:"미리보기 작게",create:"링크 만들기",creating:"만드는 중…",update:"바꾼 내용 저장",updating:"저장하는 중…",asNew:"새 링크로",reset:"예시로 되돌리기",saved:"저장했어요. 링크는 그대로예요.",created:"링크가 생겼어요",copy:"복사",copied:"복사했어요",open:"열어 보기",share:"공유",close:"닫기",keyNote:"고치기 열쇠는 이 브라우저에만 있어요. 다른 기기에서 고치려면",keyLost:"이 브라우저는 고치기 열쇠를 저장하지 못했어요. 나중에 고치려면 꼭",copyEdit:"고치기 링크 복사",copyEditShort:"고치기 링크",mine:"내가 만든 페이지",load:"불러오기",del:"지우기",delSure:"정말 지울까요?",deleted:"링크를 지웠어요.",remixed:"받은 페이지를 불러왔어요. 고친 뒤 새 링크로 만들어져요.",uploading:"올리는 중…",imgErrors:{type:"사진 파일만 올릴 수 있어요.",big:"사진이 너무 커요. 다른 사진을 골라 주세요.",limit:"사진을 너무 많이 올렸어요. 잠시 뒤에 다시 해 주세요.",fail:"사진을 올리지 못했어요. 잠시 뒤 다시 해 주세요."},errors:{"real-name":"실제로 있는 사이트나 언론사 이름은 쓸 수 없어요. 이야기 속 이름으로 바꿔 주세요.",empty:"제목(메신저는 말풍선 하나, SNS 는 본문)을 채워 주세요.",limit:"잠시 뒤에 다시 눌러 주세요.",gone:"이 링크는 지워졌거나 고칠 수 없어요. 새 링크로 만들어 주세요.",fail:"저장하지 못했어요. 잠시 뒤 다시 해 주세요.",load:"페이지를 불러오지 못했어요.",login:"로그인이 필요하거나 풀렸어요. 내 작품함에서 로그인한 뒤 다시 눌러 주세요."},fields:{site:"커뮤니티 이름",board:"게시판",title:"제목",author:"글쓴이",time:"시각",views:"조회",likes:"추천",body:"본문",comments:"댓글",name:"닉네임",text:"내용",reply:"답글",op:"글쓴이",outlet:"언론사",section:"분야",subtitle:"부제",reporter:"기자",photo:"사진",photos:"사진",addPhoto:"+ 사진",caption:"사진 설명",related:"관련 기사",room:"대화방 이름",members:"인원",theme:"말풍선",unread:"안 읽음 1",messages:"대화",mineSide:"나",otherSide:"상대",otherFallback:"상대",anon:"ㅇㅇ",replyMark:"ㄴ",addOther:"+ 상대 말",addMine:"+ 내 말",add:"+ 추가",snsName:"이름",handle:"아이디",verified:"인증 표시",dark:"어두운 화면",replies:"답글 수",reposts:"재게시",snsLikes:"좋아요",snsViews:"조회수",thread:"답글",up:"위로",remove:"빼기",artist:"아티스트 이름",avatar:"프로필 사진",fan:"내 닉네임(구독자 화면)",days:"구독 일수",bubbleView:"누구 화면",viewFan:"구독자 기준",viewArtist:"아티스트 기준",viewHint:"구독자 화면엔 아티스트 글과 내 닉네임 답장만 보여요. 아티스트 화면엔 모든 팬 답장이 보여요.",artistSide:"아티스트",fanSide:"팬",addArtist:"+ 아티스트 글",addFan:"+ 팬 답장",hiddenInFan:"다른 팬 답장이라 구독자 화면엔 안 보여요"},themes:{yellow:"노랑",blue:"파랑",dark:"어둠"}},my:{title:"내 작품함",back:"만들러 가기",chip:"내 작품함",login:"Google로 로그인",loginShort:"로그인",logout:"로그아웃",guest:"로그인하면 폰을 짧은 링크로 저장하고, 다른 기기에서도 내 작품을 모아 볼 수 있어요.",signedIn:e=>e?"".concat(e,"로 로그인했어요"):"로그인했어요",phones:"폰",phonesGuest:"로그인 없이 만든 폰은 이 브라우저에만 기억되고 30일이 지나면 사라져요. 계속 남기려면 로그인해 주세요.",phonesEmpty:"저장한 폰이 아직 없어요.",draft:"이 기기에서 꾸미던 폰 \xb7 아직 저장 안 됨",keepEditing:"이어서 꾸미기",pages:"소설 속 페이지",pagesEmpty:"만든 페이지가 아직 없어요.",pagesGuest:"고치기 열쇠가 이 브라우저에만 있어요. 로그인하면 계정에 모아 두고 다른 기기에서도 고칠 수 있어요.",localOnly:"이 기기에만",hidden:"신고로 내려감",views:e=>"조회 ".concat(e.toLocaleString("ko-KR")),edit:"고치기",view:"보기",copy:"링크 복사",copied:"복사했어요",del:"지우기",delSure:"정말 지울까요?",editSure:"초안을 덮어요. 한 번 더",removedLocal:"이 기기 목록에서 뺐어요(이 기기 열쇠로는 고칠 수 없는 페이지였어요).",claim:e=>"이 브라우저에서 만든 작품 ".concat(e,"개를 내 계정에 넣을까요? 넣으면 다른 기기에서도 고칠 수 있고, 로그인 없이 만든 폰도 사라지지 않아요."),claimBtn:"계정에 넣기",claimed:e=>"".concat(e,"개를 계정에 넣었어요."),guestUntil:e=>"임시 \xb7 ".concat(e,"까지"),loading:"불러오는 중…",error:"목록을 불러오지 못했어요. 잠시 뒤 다시 열어 주세요.",failed:"처리하지 못했어요. 잠시 뒤 다시 해 주세요.",mineLink:e=>"내가 만든 페이지 ".concat(e,"개 \xb7 내 작품함에서 보기")},viewer:{fiction:"소설 속 가상의 페이지예요.",make:"나도 만들기",report:"신고",reportSure:"이 페이지를 신고할까요?",reported:"신고를 받았어요.",gone:"이 페이지는 지워졌거나 내려갔어요."}},n={meta:{title:"Fake Phone & Social Media AU Maker — Textfic, Fake News Article & Forum Post Links | Wimo Universe",description:"Build a fake phone for your bias or OC — lock screen, passcode and hint, texts, calls, notes, photos, social feed, and music — then share it as a link. Readers need the passcode to open it. Also make in-story pages for your fic: anonymous forum posts with comments, news articles, messenger chats, and social posts. No sign-up, works right on your phone.",ogTitle:"Fake Phone & Social Media AU Maker",ogDescription:"Design a phone from the lock screen to chats and social, share it as a link, and build in-story forum posts, news articles, and messenger scenes.",keywords:["fake phone generator","social media au maker","fake text message generator","textfic","kpop au","fanfic phone","fake news article generator","fake forum post","oc phone","in-story social media","fake instagram post","sms au","social media au template","fake phone screen","story phone","ao3 social media au","ao3 texting au","fake instagram live generator","fake livestream chat","ao3 work skin alternative"]},page:{title:"Fake Phone & Social Media AU Maker",intro:'Make the "in-story screens" you drop into your fic. The phone maker opens first: fill your bias or OC\'s lock screen notifications, four-digit passcode and hint, text conversations, missed calls, notes, photos, and social feed, and choose which apps sit on the home screen. Hit "Make link" and readers enter the passcode to open the phone. For scenes outside the phone, pick "In-story pages" above to build an anonymous forum post with comments, an online news article, a messenger chat, a social post, or a Bubble-style idol fan chat, each as a short link starting with wimouniv.com/pota/.'},related:{before:"Drop your OC into a villainess novel: the ",link:"Isekai Life Simulator",after:" gives them a random role and plays out their whole life, death flags and all, on a card with their name."},headings:{howTo:"How to use it",faq:"Frequently asked questions",otherTools:"More tools"},steps:["The phone maker opens first. In Basics, set the phone owner's name, the four-digit passcode, the hint shown after a wrong try, and the wallpaper. Leave the passcode empty and the phone opens right away.","On the Home Screen tab, turn apps on or off or move them to the dock below. Fill the notifications, messages, calls, notes, photos, and social tabs and the phone above switches to that app screen so you can see how it looks.",'Add an "incoming call" in the calls tab or "conversation continues" in the messages tab, and after unlocking readers can answer the call or tap the keyboard to keep the story going.','Tap "Make link" and a short link is copied. Links made without signing in open for 30 days. Paste it into your fic, an X thread, or a chat, and readers unlock it and open each app one by one.','For scenes outside the phone, pick a forum post, news article, messenger, social post, or Bubble-style idol fan chat under "In-story pages" above. Fill in the fields and tap "Make link" for a short link that keeps working even after you edit the content later.','In-story pages collect under "My pages" in this browser. Load them again to edit, or delete the link.'],faqs:[{q:'What is the "fourth pota revolution"?',a:'In Korea, writers on Postype call this the "fourth pota revolution": dropping fake screens into a fic as links — the lead\'s phone, an in-story forum post, a news article — so readers step into that world and look around for themselves. Here it means the same thing for fanfic, social media AUs, and textfics on AO3, Wattpad, or X threads. You just fill in fields instead of building each page with an AI website builder.'},{q:"How do readers know the phone passcode?",a:"Swipe up on the lock screen and the passcode screen appears. After one wrong try, the hint you wrote shows at the top. Pick a number only readers who know the story can guess, like a character's birthday or the day they first met. Leave the passcode empty and the phone opens straight to the home screen."},{q:"Where is what I make saved?",a:"Phones and in-story pages are both saved on WIMO's server (Google Cloud Firestore). A phone saved after signing in with Google stays in My Works. A phone link made without signing in opens for 30 days and is then deleted, so to keep it, sign in from the same browser and add it to your account. The key to edit or delete stays in the browser that made it. The passcode is part of the phone data. Uploaded photos go to WIMO storage. Anyone with the link can view it, so never put real private information or secrets in one."},{q:"Can I change a link that is already out?",a:'Yes for in-story pages. Edit the content in the browser where you made it and tap "Save changes": the same link opens with the new content. You can use it to add one teasing comment at a time while you post chapters. Phones work the same way: edit in the browser that made it and tap "Save (same link)". Older long phone links hold the phone inside the link itself, so editing those makes a new link.'},{q:"Can I change the apps on the home screen?",a:"Yes. On the Home Screen tab, choose Home, Dock, or Off for each app, and use the arrows to change the order on Home. The dock holds up to four apps. The photo and social apps can be renamed, and you can fill the profile and up to 12 posts. An app you turn off only disappears from the home screen; tapping its lock screen notification still opens it."},{q:"Can I add photos?",a:"Yes. On a phone, photos can go on the wallpaper, in the photo library (18), in social posts, and in Messages, KakaoTalk and WhatsApp chats. In-story pages take up to 4 photos on forum and social posts, 1 lead photo for a news article, and 1 per messenger message. Photos are resized to 1,600px on the long side on your device before upload, usually landing at 200–400KB each; anything still over 1MB after resizing is rejected. Don't upload other people's photos or real faces without permission."},{q:"Can I take a phone I received and make it mine?",a:'Yes. On a phone opened from a link, tap the "Make yours" chip in the bottom corner, then "Remix this phone" to load its content into the editor. Change what you like, tap "Make link" again, and you get a new link.'},{q:"Can I make a call come in or a conversation continue?",a:'In the calls tab, add a name and lines under "Incoming call" and it rings a few seconds after unlocking. If readers answer, the lines appear one by one; if they miss it, the message you left arrives in the conversation. Under "Conversation continues" in the messages tab, each tap on the keyboard writes more of the reader\'s line, and the other person replies after they send it.'},{q:"Can I make it with AI?",a:'Yes. Tap "Fill with AI" below the phone and use "Copy prompt" to hand the guide to Claude or ChatGPT. Add your characters and situation and the AI writes the notifications, conversations, notes, and social posts all at once. Paste its answer into the field and tap "Load" so you don\'t have to fill each menu by hand. Photos and voice files still have to be uploaded yourself.'},{q:"Can I make a fake Instagram Live or livestream scene?",a:'Yes. Open the Live tab on the phone and fill in who is streaming, the stream title, viewer and heart counts, a background photo, a pinned comment, and the chat. Readers get a livestream screen where comments pop in one by one and hearts float up when they tap. It works well for the "they went live at 2 a.m." beat in an idol AU or celebrity AU.'},{q:"How do I use it in an AO3 fic?",a:'AO3 lets you put links and images in a chapter, but it only embeds a short allowlist of sites (YouTube, SoundCloud and the like) and blocks scripts, so there are two ways. Link it: make your phone or in-story page, copy the link, and add it to your chapter text as a regular link (for example "open Jaehyun\'s phone"). Show it: open the link, take a screenshot, host the image, and add it to the chapter with an image tag. It is the no-code alternative to building a texting or social media work skin by hand, and readers on mobile can tap through the whole phone.'},{q:"Is there a Halloween version?",a:"There is a Halloween Night wallpaper in Basics, so the lock and home screens turn pumpkin orange and dark purple. Pair it with a horror AU group chat or a 3 a.m. livestream that goes wrong."},{q:"What if someone uses it to mislead people?",a:"Please don't use it to impersonate real people, or to pass off real chat screenshots or a real news story as if it were true. In-story pages have a Report button, and pages reported by several people are hidden automatically. Link pages are kept out of search results."}],kinds:{board:"Forum post",news:"News article",chat:"Messenger",sns:"Social post",bubble:"Bubble"},hub:{nav:"What to make",phone:"Design a phone",phoneSub:"Lock screen to chats and social",more:"In-story pages",navPages:"Choose a page"},ui:{urlEmpty:"Make a link to get an address",dockBig:"Bigger preview",dockSmall:"Smaller preview",create:"Make link",creating:"Making…",update:"Save changes",updating:"Saving…",asNew:"As a new link",reset:"Reset to sample",saved:"Saved. Your link stays the same.",created:"Your link is ready",copy:"Copy",copied:"Copied",open:"Open",share:"Share",close:"Close",keyNote:"The edit key lives only in this browser. To edit on another device,",keyLost:"This browser couldn't save the edit key. To edit later, be sure to",copyEdit:"Copy edit link",copyEditShort:"Edit link",mine:"My pages",load:"Open",del:"Delete",delSure:"Delete for sure?",deleted:"Link deleted.",remixed:"Loaded the page you received. Edit it and make a new link.",uploading:"Uploading…",imgErrors:{type:"You can only upload image files.",big:"That photo is too large. Please choose another one.",limit:"You uploaded too many photos. Try again in a moment.",fail:"Couldn't upload the photo. Please try again in a moment."},errors:{"real-name":"You can't use the name of a real site or news outlet. Please use a name from your story.",empty:"Fill in the title (for messenger, one message; for social, the post body).",limit:"Please try again in a moment.",gone:"This link was deleted or can no longer be edited. Please make a new link.",fail:"Couldn't save. Please try again in a moment.",load:"Couldn't load the page.",login:"You need to be signed in, or your sign-in expired. Sign in from My Works and try again."},fields:{site:"Community name",board:"Board",title:"Title",author:"Author",time:"Time",views:"Views",likes:"Upvotes",body:"Body",comments:"Comments",name:"Name",text:"Text",reply:"Reply",op:"OP",outlet:"Publication",section:"Section",subtitle:"Subtitle",reporter:"Reporter",photo:"Photo",photos:"Photos",addPhoto:"+ Photo",caption:"Caption",related:"Related stories",room:"Conversation name",members:"Members",theme:"Bubble color",unread:"Unread 1",messages:"Messages",mineSide:"Me",otherSide:"Them",otherFallback:"Them",anon:"Anon",replyMark:"↳",addOther:"+ Their line",addMine:"+ My line",add:"+ Add",snsName:"Name",handle:"Username",verified:"Verified badge",dark:"Dark mode",replies:"Replies",reposts:"Reposts",snsLikes:"Likes",snsViews:"Views",thread:"Replies",up:"Move up",remove:"Remove",artist:"Artist name",avatar:"Profile photo",fan:"My nickname (fan view)",days:"Days subscribed",bubbleView:"Whose screen",viewFan:"Fan view",viewArtist:"Artist view",viewHint:"The fan view shows only the artist’s messages and replies from your nickname. The artist view shows every fan’s reply.",artistSide:"Artist",fanSide:"Fan",addArtist:"+ Artist message",addFan:"+ Fan reply",hiddenInFan:"Another fan’s reply, hidden in the fan view"},themes:{yellow:"Yellow",blue:"Blue",dark:"Dark"}},my:{title:"My Works",back:"Back to the maker",chip:"My Works",login:"Sign in with Google",loginShort:"Sign in",logout:"Sign out",guest:"Sign in to save phones as short links and see everything you make on any device.",signedIn:e=>e?"Signed in as ".concat(e):"Signed in",phones:"Phones",phonesGuest:"Phones made without signing in are remembered only in this browser and disappear after 30 days. Sign in to keep them.",phonesEmpty:"You haven't saved any phones yet.",draft:"Phone you were working on (this device) \xb7 not saved yet",keepEditing:"Keep editing",pages:"In-story pages",pagesEmpty:"You haven't made any pages yet.",pagesGuest:"Edit keys are stored only in this browser. Sign in to keep them in your account and edit on other devices.",localOnly:"This device only",hidden:"Taken down after reports",views:e=>1===e?"1 view":"".concat(e.toLocaleString("en-US")," views"),edit:"Edit",view:"View",copy:"Copy link",copied:"Copied",del:"Delete",delSure:"Delete for sure?",editSure:"Replaces your draft. Tap again",removedLocal:"Removed from this device's list (this device's key couldn't edit it).",claim:e=>"Add ".concat(e," item").concat(1===e?"":"s"," made in this browser to your account? Then you can edit them on other devices, and phones made without signing in will not expire."),claimBtn:"Add to account",claimed:e=>"Added ".concat(e," to your account."),guestUntil:e=>"Temporary \xb7 until ".concat(e),loading:"Loading…",error:"Couldn't load the list. Please try again shortly.",failed:"Something went wrong. Please try again shortly.",mineLink:e=>"".concat(e," page").concat(1===e?"":"s"," you made \xb7 see them in My Works")},viewer:{fiction:"This is a fictional in-story page.",make:"Make your own",report:"Report",reportSure:"Report this page?",reported:"Thanks, we received your report.",gone:"This page was deleted or taken down."}},s=e=>"en"===e?n:t}}]);